private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // Handle nulls
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }

    int strLen = str.length();
    int suffixLen = suffix.length();

    if (suffixLen > strLen) {
        return false;
    }

    // Empty suffix matches any string
    if (suffixLen == 0) {
        return true;
    }

    try {
        if (ignoreCase) {
            // Using regionMatches for case-insensitive compare
            return str.regionMatches(true, strLen - suffixLen, suffix, 0, suffixLen);
        } else {
            return str.endsWith(suffix);
        }
    } catch (Exception e) {
        // In case of any unexpected runtime exception, treat as non-match
        return false;
    }
}

