    // If the prefix is longer than the string, it cannot match
    if (prefix.length() > str.length()) {
        return false;
    }

    try {
        // Use regionMatches with the ignoreCase flag for efficient comparison
        return str.regionMatches(ignoreCase, 0, prefix, 0, prefix.length());
    } catch (SecurityException | StringIndexOutOfBoundsException e) {
        // Unexpected runtime issues – treat as non-match
        return false;
    }
}

