    if (node == null) {
        throw new IllegalArgumentException("node cannot be null");
    }
    if (node.left == null) {
        throw new IllegalArgumentException("node.left is null, right rotation not possible");
    }
    TreeNode<T> leftChild = node.left;
    // Detach leftChild's right subtree and attach to node
    node.left = leftChild.right;
    if (leftChild.right != null) {
        leftChild.right.parent = node;
    }
    // Update parent reference
    leftChild.parent = node.parent;
    if (node.parent == null) {
        // node was root; after rotation leftChild becomes the new root
    } else {
        if (node.parent.left == node) {
            node.parent.left = leftChild;
        } else {
            node.parent.right = leftChild;
        }
    }
    // Reattach node as right child of leftChild
    leftChild.right = node;
    node.parent = leftChild;
    return leftChild;
}

