private int computeBinaryLog(int n){
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be positive: " + n);
    }
    try {
        // floor(log2(n)) + 1 equals the position of the highest set bit (1-indexed)
        return 32 - Integer.numberOfLeadingZeros(n);
    } catch (Exception e) {
        // Wrap any unexpected runtime issue
        throw new RuntimeException("Failed to compute binary log for n=" + n, e);
    }
}

