private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Basic argument validation
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate cannot be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }

    // Create a circulator starting at the specified node in the given direction
    OuterFaceCirculator c;
    try {
        c = new OuterFaceCirculator(start, dir);
    } catch (Exception e) {
        throw new IllegalStateException("Failed to create OuterFaceCirculator", e);
    }

    // If the start node is already the stop node, return the circulator immediately
    if (c.node().equals(stop)) {
        return c;
    }

    // Traverse the outer face boundary until we either find a matching node
    // or reach the stop node.
    try {
        while (!c.node().equals(stop)) {
            if (predicate.test(c.node())) {
                return c;
            }
            c.next();  // advance to the next node along the boundary
        }
        // At this point we have reached the stop node; return its circulator
        return c;
    } catch (Exception e) {
        // Wrap any runtime exception in a unchecked exception for consistency
        throw new RuntimeException("Error while selecting node on outer face", e);
    }
}

