private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    for (K key : keys) {
        try {
            if (key == null) {
                bounds.add(Integer.MAX_VALUE);
            } else if (key instanceof Number) {
                bounds.add(((Number) key).intValue() + 1);
            } else {
                bounds.add(key.hashCode());
            }
        } catch (Exception e) {
            // If any unexpected exception occurs, use Integer.MAX_VALUE as a safe fallback.
            bounds.add(Integer.MAX_VALUE);
        }
    }
    return bounds;
}

