private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    int len = input.length();
    if (len == 0) {
        return input;
    }

    StringBuilder sb = new StringBuilder(len);
    int i = 0;
    // Remove surrounding quotes if present
    boolean quoted = false;
    if (len >= 2 && input.charAt(0) == '"' && input.charAt(len - 1) == '"') {
        quoted = true;
        i = 1;
        len -= 1; // exclude closing quote
    }

    while (i < len) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            i += 2; // consume backslash and next char
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case 'x':
                    // hex escape: try 2 or 4 hex digits
                    int hexDigits = 0;
                    if (i + 1 < len && isHexDigit(input.charAt(i)) && isHexDigit(input.charAt(i + 1))) {
                        hexDigits = 2;
                    } else if (i + 3 < len &&
                               isHexDigit(input.charAt(i)) && isHexDigit(input.charAt(i + 1)) &&
                               isHexDigit(input.charAt(i + 2)) && isHexDigit(input.charAt(i + 3))) {
                        hexDigits = 4;
                    }
                    if (hexDigits > 0) {
                        String hex = input.substring(i, i + hexDigits);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                        } catch (NumberFormatException e) {
                            // Fallback: keep the raw representation
                            sb.append("\\x").append(hex);
                        }
                        i += hexDigits;
                    } else {
                        // Not a valid hex escape, keep literal
                        sb.append("\\x");
                    }
                    break;
                default:
                    // Any other escaped character is taken literally
                    sb.append(next);
                    break;
            }
        } else {
            sb.append(c);
            i++;
        }
    }

    return sb.toString();
}

