private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    try {
        while (bb.hasRemaining()) {
            int first = bb.get() & 0xFF;
            if ((first & 0x80) == 0) { // 1-byte sequence
                sb.append((char) first);
                i++;
            } else if ((first & 0xE0) == 0xC0) { // 2-byte sequence
                if (!bb.hasRemaining()) break;
                int second = bb.get() & 0x3F;
                int codePoint = ((first & 0x1F) << 6) | second;
                sb.append((char) codePoint);
                i++;
            } else if ((first & 0xF0) == 0xE0) { // 3-byte sequence
                if (bb.remaining() < 2) break;
                int second = bb.get() & 0x3F;
                int third = bb.get() & 0x3F;
                int codePoint = ((first & 0x0F) << 12) | (second << 6) | third;
                sb.append((char) codePoint);
                i++;
            } else if ((first & 0xF8) == 0xF0) { // 4-byte sequence (surrogate pair)
                if (bb.remaining() < 3) break;
                int second = bb.get() & 0x3F;
                int third = bb.get() & 0x3F;
                int fourth = bb.get() & 0x3F;
                int codePoint = ((first & 0x07) << 18) | (second << 12) | (third << 6) | fourth;
                sb.appendCodePoint(codePoint);
                i++;
            } else { // Invalid leading byte
                sb.append('\uFFFD'); // Unicode replacement character
                i++;
            }
        }
    } catch (Exception e) {
        // On any exception, append a replacement and stop decoding
        sb.append('\uFFFD');
    }
    return i;
}

