public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new NullPointerException("The URI must not be null");
    }
    String path = u.getPath();
    List<PathSegmentImpl> result = new ArrayList<>();
    if (path == null || path.isEmpty()) {
        return result;
    }
    // Remove leading '/' if present because it is not a delimiter for the first segment
    if (path.charAt(0) == '/') {
        path = path.substring(1);
    }
    // If the path is now empty, there are no segments to return
    if (path.isEmpty()) {
        return result;
    }
    // Split by '/' keeping trailing empty segments
    String[] parts = path.split("/", -1);
    for (String part : parts) {
        String segment = part;
        if (decode) {
            try {
                segment = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (IllegalArgumentException | java.io.UnsupportedEncodingException e) {
                // If decoding fails, keep the original percent‑encoded string
            }
        }
        result.add(new PathSegmentImpl(segment));
    }
    return result;
}

