public final boolean isTemplateVariablePresent(String name){
    if (name == null || name.isEmpty()){
        return false;
    }
    try {
        // Attempt to locate a field that might hold template variables
        java.lang.reflect.Field varField = this.getClass().getDeclaredField("variables");
        varField.setAccessible(true);
        Object vars = varField.get(this);

        if (vars instanceof java.util.Collection<?>) {
            return ((java.util.Collection<?>)vars).contains(name);
        }
        if (vars instanceof java.util.Map<?,?>) {
            return ((java.util.Map<?,?>)vars).containsKey(name);
        }
        if (vars instanceof String[]) {
            for (String v : (String[])vars) {
                if (name.equals(v)) return true;
            }
        }
    } catch (NoSuchFieldException | IllegalAccessException ignored) {
        // No 'variables' field; fall back to checking all declared fields
        for (java.lang.reflect.Field f : this.getClass().getDeclaredFields()) {
            if (name.equals(f.getName())) {
                return true;
            }
        }
    } catch (Exception ignored) {
        // Any other exception is ignored; method will return false
    }
    return false;
}

