    // Validate total size
    int size = totalSize;
    if (size < 0) {
        throw new IllegalStateException("Total size is negative");
    }

    byte[] result = new byte[size];
    int offset = 0;

    for (int i = 0; i < bufferList.size(); i++) {
        byte[] buf = bufferList.get(i);
        int len = bufferLengths.get(i);

        // Validate buffer length for safety
        if (len < 0 || len > buf.length) {
            throw new IllegalStateException("Invalid buffer length at index " + i);
        }

        System.arraycopy(buf, 0, result, offset, len);
        offset += len;
    }

    return result;
}

