public byte[] toByteArray(){
    // Return a copy of the internal byte array to avoid exposing mutable state.
    // If the internal array is null, return an empty array.
    if (bytes == null) {
        return new byte[0];
    }
    try {
        byte[] copy = new byte[bytes.length];
        System.arraycopy(bytes, 0, copy, 0, bytes.length);
        return copy;
    } catch (OutOfMemoryError e) {
        // Wrap out‑of‑memory errors in a RuntimeException so callers can see the problem.
        throw new RuntimeException("Unable to allocate memory for byte array copy", e);
    } catch (Exception e) {
        // Catch any unexpected exception and wrap it in a RuntimeException.
        throw new RuntimeException("Unexpected error while copying byte array", e);
    }
}

