    try {
        // If the current field uses the length‑delimited wire type, it may be a packed
        // repeated field.  Update the parsing state accordingly, but only if we have a
        // descriptor for the field and if the descriptor indicates that the field is packed.
        if (currentWireType == WIRETYPE_LENGTH_DELIMITED) {
            FieldDescriptor field = getFieldDescriptor(currentFieldNumber);
            if (field != null && field.isPacked() && !isReadingPacked) {
                isReadingPacked = true;
            } else {
                isReadingPacked = false;
            }
        } else {
            // For any other wire type, packed mode cannot be active.
            isReadingPacked = false;
        }
    } catch (Exception e) {
        // Wrap any unexpected exception in an IOException since this method is called
        // during parse operations that are expected to throw IOException on failure.
        throw new IOException("Failed to check if current field is packed", e);
    }
}

