    try {
        // Attempt to read the next varint-encoded tag from the input.
        return readRawVarint32();
    } catch (EOFException e) {
        // The protocol message may legitimately end at a tag boundary, so
        // treat an EOF as a zero (no tag) rather than propagating the exception.
        return 0;
    }
